/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20161130-14","meetingId":"h28-cm11","date":"2016年11月30日","dateIso":"2016-11-30","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時１０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"ご説明ありがとうございました。今定例会の一般質問で、私どもの会派から、こちらの土地活用についても質問させていただきまして、今日、ご報告をいただいているわけですが、その内容としては、東京都、また区は行政需要を考慮しながら、５,０００平米ということが今は出てまいりました。教えていただければ、今、お話しいただける範囲で伺えればと考えています。あわせて、その２点を伺えればと思います。","respondent":"柏原企画調整課長","answer":"どちらかというと、我々が検討しているのは区全体の大きな方針ですので、この方針に合うような形で進めていますけれども、学校独特の課題であったり、いろいろなところがありますので、そこは我々も考慮しながら。","voiceIndex":6,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのような中での５,０００平米程度ということなのですが、まず、この５,０００平米というものは、基本的には、横長のものをぶつ切りで合わせて５,０００平米ではなくて、これから東京都との調整なのでしょうけれども、一括で、全体の中で一塊になっているところが５,０００平米と思っていていいのかどうかがわかれば教えてください。","respondent":"柏原企画調整課長","answer":"ただ、最初にご説明したように、東京都がここ全体を避難場所として拡張したいというところは前々から申しておりますので、現在、東京都とも調整を図るべく、いろいろなお話はさせていただいているところではあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。やはりまとまっているほうがさまざまな使い道はあると思いますし、また、今後のお話し合いの中での進捗状況等も出てまいると思います。行政需要もさまざまなニーズがあると思いますので、徐々にではありましょうけれども、また方向性とかが出てきたら、この委員会等で報告いただければと思います。要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"林試の森、旧小山台住宅についてお伺いしたいと思います。まとまった土地の５,０００平米のほかに、この区道に沿った部分を、例えば、少し区が用地を買収というようなことも考えられているのかということを確認させていただきたいと思います。会派としても求めてまいりました。その上で、この道路の拡幅が、どういうふうなまちづくりになっていくのかということをお聞かせいただきたいと思います。","respondent":"柏原企画調整課長","answer":"いずれにしましても、区としては、その道路の問題は重要視しておりますので、改めてお話もいただいているところですが、強く進めていきたいと思ってあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"その場合は、５,０００平米とはまた別に、改めて、ある程度のところを取得するという考え方になるわけですか。地域の声でもありますので、ぜひ、国、また東京都としっかり連携しながら、そのことを進めていただきたいと思います。さっきの５,０００平米とは別に取得なのかというところだけ、再度、確認をさせてください。","respondent":"柏原企画調整課長","answer":"思いといたしましては、区は別でと考えていますけれども、これは、今の段階では、まだ国の土地ですし、東京都が全体の防災の関係で公園を大きくしたいという考え方がありますので、そことは調整しながらですが、思いとしては、別として、声を上げていきたいと思ってあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"区有施設地区別一覧の資料ですが、１２の種類の施設が並んでおりますが、この中で５つの地区別にバランスよく配置する方針がある施設はどれになるのか、区の考えを伺います。それと、小山台ですけれども、基本的な情報として、現在の住宅用途、住宅がありますが、この建物の現況、どれぐらい傷んでいるかなど、教えていただきたいと思います。スケジュール感をお伺いします。","respondent":"柏原企画調整課長","answer":"東京都が公園にしたいという関係が、かなり手続的に時間がかかると聞いてありますので、その辺も含めて、これはおそらく、国が単に通知を出して処分をするというよりは、国、東京都、区を含めての調整、話し合いは今後もしていかなくてはいけないという認識です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、小山台のほうですけれども、現地も当委員会で視察して、確認もしたのですが、旧峰友寮の北側の縦長の部分と、その上に横長の長方形が部分がついている。ここら辺を区として活用するお考えはないのか、伺います。合計２万３,０００平米余のうち、区が５,０００平米ということで、５分の１程度になるわけですけれども、それしか取得しない理由があれば伺います。","respondent":"柏原企画調整課長","answer":"ですので、これは区としても、財政措置としてはかなり大きなものになりますので、すぐ、では、という話にはなりませんので、逆に、行政需要の部分から考えたときに、先ほど申しましたけれども、高い建物が建ちませんので、例えば福祉施設、一定程度、面積を確保といった場合に。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"そのほかの都有地について、後段に伺った水色の通路の下にちょっとある都有地があったと思うのですが、そちらについてはどうなのかというのをあわせてお伺いしたいと思います。行政需要はたくさんあると思いますので、お金はもちろんかかりますが、区がこれまで備えてきた基金もしっかりあることですし、ぜひ、５,０００平米にとどまらず、購入をすべきだと思いますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"単にここが全部あればとかという部分よりは、そういった防災に関する大きな施策の部分も考えながら、区としては進めなくてはいけないというのも１つありますので、今後の話し合いというのはどこまで、どういった形で進められるかというところはありますけれども。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"防災のところの考えは、もちろん防災も大事だと考えています。ちょっとお伺いしたいのは、面積が一番小さいということも紹介されましたけれども、現在の基準として、１人当たりの面積を満たしていないということなのか、それとも、満たしてはいるのだけれども、１人当たりの面積が一番小さいということになっているのか伺います。","respondent":"柏原企画調整課長","answer":"東京都から聞いてありますのは、これは満たしていないというよりは、東京都が避難有効面積ということで、１人当たりの避難有効面積は１平米ということを基準に持っているようです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"安藤委員","kind":"意見","question":"すみません。１人当たりの有効面積が１平米を大きく超えるということになることなのですが、１平米を下回っているというのは、確かに基準以下ということで、それは改善する必要があると思いますが、１平米というところまで改善したとしても、５,０００平米より多く残ると考えていますので、できる限り、そうした防災と行政需要の充実の両立に向けて、今後とも工夫をしていただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"小山台小学校そのものも広くなるし、そうすれば、ここに新たに学級数を増やした学校が建てられる。ちょうど学校用地としても最適なところにありますし、緑に囲まれた学校ということで、今までの小山台小学校のところは、これができた後は、いろいろまた、４６号線に面しているので、使い勝手もいい形になるので、このような形で、教育施設として、学校用地として買うというのは頭の中にはないのでしょうか。","respondent":"柏原企画調整課長","answer":"建物の大きさ、広さというところを考えたときに、学校の敷地ということになりますと、校庭の部分といったところも一定程度、確保しなくてはいけないというのがありますので、教育なり文化というところでの施設というのは、１つ。","voiceIndex":26,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"これは町会長から陳情がよく出るのですけれども、私たちは目黒区に行ったほうがいいのだと。電話番号も目黒区局なのだそうです。やはり旧小山台住宅のところを住宅にしてもらって、家並みがそろっていると、俺たちも品川区民だという気がするんだろうという声が出ているのですけれども、こういう考え方は、これを買う東京都、品川区の頭の中にあるのでしょうか。その辺をお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"ここの土地を取得して行政需要を満たしていこうという中で、そういったところも、区としては考慮、配慮、そういったところを考えながら、何かうまい施策ができないかどうかというのは検討していきたいと思ってあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"その点は本当に検討してもらいたいと思います。東京都が買う用地の中で、私の聞いている話では、消防の出張所をこちらに移転する話もあるやに聞いているのですけれども、このような情報は品川区には入っているのでしょうか。その辺もお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"消防庁の出張所が、今、建替えに向けて土地を探しているというところはお話を聞いておりまして、一部、この国家公務員宿舎も想定したいというお話は聞いているところです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"区有施設のほうからお伺いしたいと思います。荏原地域も意外に多いと思いながら見ていたのですけれども、大崎エリア、品川エリアで、相当に人口が近年、増えてきておりますが、区として、今のエリアバランスについて、どのようにお考えかというのが１点。それと、ちょっと細かい話なのですけれども、日光の光林荘は、区外教育施設には入らないのですか。表ではどういうことになっているのか教えてください。","respondent":"柏原企画調整課長","answer":"例えば、いろいろ議会でもご議論いただいております東品川の清掃作業所跡をはじめ、一定程度、役割を完了しているだろうといった施設もありますので、全体の清掃の業務といったところも考えながら、その再編というのは検討しなければいけないと思っています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"清掃なのですけれども、これは全体の中で議論していくことになるのか、それとも、清掃施設だけで１つくくって、今後、庁内で検討していくことになるのか、これについては時間もある程度、区切られているといいますか、タイミングを合わせて議論すべきことだと考えていますので、清掃についての検討体制をどのようにお考えかを教えてください。しながわ荘はこれに入っていないのでしたか。確認だけです。","respondent":"柏原企画調整課長","answer":"清掃の部分です。我々といたしましては、もちろん清掃業務というのは大きくあるところですので、その部分については考えるのですけれども、施設のあり方というところを考えたときに、清掃の施設は全体を見ながらというところで検討をしていきたいと思ってあります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうすると３にならないか。それから、２つ目の小山台のほうなのですが、これは本当に長年、売却の話が出たころから、まだ住民の方が住んでいらっしゃるころから、いろいろな会派、私どもも含めて、いろいろ要望をしてきて、ようやく具体的に動きが見えてきたと、随分かかったと感じております。そういったことも考えていたら教えてください。どういう分担で拡幅をやっていくことになるのかと思います。","respondent":"柏原企画調整課長","answer":"建物のお話もありましたけれども、今、想定していますのは、建物が幾つか並ぶというよりは、１つの建物で行政需要を満たしたいということで、その行政需要につきましては、単体のものではなく、複数も想定しながらということで検討をできればと思ってあります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"すみません、１点。道路なのですけれども、ここを区で整備するということは、ここに隣接するエリアで考えていらっしゃるということなのでしょうか。どうなのでしょうか。道路の拡幅と、土地の取得や整備と、東京都としての防災公園の整備のタイミングというのは、それぞれ分けて考えていらっしゃるのですか。どのような形で進んでいくのでしょうか。","respondent":"柏原企画調整課長","answer":"清掃の部分につきましては、全体として検討をしていきたいということで、こういった跡地活用であったり、公有地の活用というのは、企画部門を中心に動いておりますので、我々が所管部門と協力体制をつくりながら、我々が中心になりながら。","voiceIndex":38,"id":"exchange-017"},{"speaker":"あべ委員","kind":"意見","question":"清掃のほうは、東品川だけではなくて、多分、荏原あたりも対象に入ってくると考えています。いろいろ技術的な問題もあると思いますので、ぜひ、現場の声をよく聞きながら検討を進めていただければと思います。道路のほうは、できるだけ早く、広い状態でつながるように、ぜひよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-018"}]},{"id":"topic-02","title":"補助金・助成金のあり方に関すること","agenda":"補助金・助成金のあり方に関すること","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この表は非常にきれいにできていて、とてもわかりやすいのですけれども、つまり、これは品川区の場合は具体的にどうなっているのかというのがちょっとわかりにくいものですから、例えば、いきなりこれを伺って、数字が出てくるか。それが3)の執行のところに行って、条例や規則に基づいているものがどのくらいの割合で、要綱に基づいているものがどのくらいの割合でというのは出てくるものなのですか。","respondent":"秋山財政課長","answer":"そういう意味で、ここにも書かせていただいておりますけれども、社会の情勢が変化しているかという視点で見ていったときに、例に出された団体の補助が一定額で何年も来ているというのが、そういう意味からすると。","voiceIndex":46,"id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"件数は出てこなかったのですけれども、かなりの数字だったと考えています。３４４億円強、一般会計で直すと４分の１弱ぐらいになるのですか。相当な割合を占めていると思いますし、その性格もさまざまですから、一括してどうだというのはなかなか言いにくい。こちらとしても言いにくいし、答弁としても言いにくいところがあるだろうと考えています。そうなのですかということをお伺いしたいと思います。","respondent":"秋山財政課長","answer":"企画部門として、この仕組みが、今、完璧なものなのかというお問い合わせをいただければ、それは常によりよくしていかなければいけないだろうし、そこは考えていかなければいけないだろうという課題だとは考えております。","voiceIndex":48,"id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"もうちょっと具体的に。常によりよくしていかなければいけないというのは、例えば、今、どういう部門をよりよくしていかなければいけないのか、何を考えていこうと思っているのかを教えてください。","respondent":"中山企画部長","answer":"そういう意味では、例えば団体助成したときに、団体の活動が活性化しているかというのは、予算編成の中でどういう事業をされているかというものを聞きながらやるというのもありますけれども、１つの取組みとして、これは国全体でもあるのですが。","voiceIndex":50,"id":"exchange-021"},{"speaker":"あべ委員","kind":"意見","question":"入口の議論なので、なかなか具体的にはなっていかないのですけれども、やはり現場は現場で、かなりこの評価というのは悩んでいる部分も大きいと思うのです。だから、そこをしっかり拾って、目に見える形にしていく努力が必要だと。今日はこのあたりにしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"例えば介護の施設でもそうですけれども、介護の事業をやっているのだけれども、違う業態でやろうとか、保育園がもしかして、この先、どんどん減ってきたときに、保育所が変わってきて、例えば幼稚園に変えるときに、最初に出した補助金は、その目的とは変わってくることがあるではないですか。もうできているものに対して、どうやってその対応をしているのかというのを聞かせてください。","respondent":"秋山財政課長","answer":"どういう縛りをかけているかということになるかと思うのですけれども、区の中で、細かく個々の要綱まで私は承知していないのですが、年数的な縛りを明確に書いてあるというのは私の記憶ではなかった感じがしますけれども、すみません、正確にはお答えできないで申し訳ありません。","voiceIndex":53,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"そういった施設関係の補助で、実際、そういうことは今まであるのですか。途中で、その目的で出したけれども、急に続けられなくなってしまって、もうやめました、補助金は高齢者の施設で出していて、すぐやめることになってしまった、そういうことはどういう対応をされているのか。","respondent":"秋山財政課長","answer":"区単独で出したもので、そういうものは承知はしておりません。","voiceIndex":55,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"２点、お伺いします。さまざまな事業に補助金が出ているわけですけれども、この中で、国や都からの補助がなく、区単独で補助金を出している事業というのは、大体、全体のうちの何割ぐらいなのかがもしわかればというのが１点です。それと、今年は過去最高の予算で、さらに土木費が過去最高と。開発補助金も過去最高値の２３０億円余だったと思います。その点についてご説明いただければと思います。","respondent":"秋山財政課長","answer":"そういう出したものがどういう形ででき上がっているのかというのがまず１点ありますし、その中で、例えば防災性の向上であれば、不燃化率の向上というところの数字が出てくると考えています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"それと、開発補助金のところですけれども、実際、お伺いしたことがわからなかった、実際、やられているのかどうかというのがよくわからなかったので、一つ一つの事業については、もちろん目的などは変わったりするというところはあると思いますが、再開発が完了した時点なのか、どの時点でどのような検証が行われているのか、いないのかというところをもう一度、お伺いします。","respondent":"秋山財政課長、藤田都市環境部長","answer":"最初のご質問ですけれども、大変申し訳ないのですけれども、単費のものが幾つかというのは、多分、１件１件、精査をしていかないとわからないので、今、私が手持ちで持っているものではお答えできないと思っています。それを開発事業者側に、区の補助分も合わせて、開発事業者を支援する形になっておりますけれども、そういうような仕組みの中では、国は、どういう効果がしっかりあったかどうか検証しなさいという形で求めておりますので。","voiceIndex":59,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお聞きしたいと思います。使い切らなかった。そういった補助金はどうされているのか。都や国から出てきた補助金というのは、実績に見合って返金をするという、計算上、出てくると思いますけれども、区がそれぞれの団体に、あるいはハード面、ソフト面、６月の資料の中で見ますと、余ったお金、残ったものは、どういうふうになっているのか教えてください。","respondent":"秋山財政課長","answer":"もちろん、その調査についても、必要な書類等を調べて、その金額についてきちっと見直して、余るようであれば戻していただきます。","voiceIndex":62,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"乏しいもの、その効果は。例えば補助金は適正なのかというところの具体的なところは、それぞれの補助金の出し方の考え方があると思うので、ここでは細かく、一つ一つを取り上げてというのはしませんが、考え方として、適正に補助金を執行していくために、今、私が申し上げた効果に乏しいものはないか、ここに挙がっているものについての検証をもう少し具体的にどうされているのか、ご説明願いたいと思います。","respondent":"秋山財政課長","answer":"６月の資料をご覧いただくと、かなりの種類のものがあります。それらについて、検証の方法を一つ一つというのはなかなか難しいものですから、ここでは効果が乏しいという１つに抽象的な言葉で書かせていただいたのが正直なところです。","voiceIndex":64,"id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"特にそちらの部分、今後、事業に対しての補助金を出す、あるいは助成金を出したというときに、区民の方に、より効果がある、そうした執行の仕方というところでの検証を今後考えて、今も考えていらっしゃると思いますが、これは常に考えていくことと先ほどもご答弁がありましたので、ぜひ、その点は、最後に確認をさせていただきたいと思います。","respondent":"秋山財政課長","answer":"先ほど常にということでお話をさせていただきましたけれども、部長からも答弁させていただきましたように、ＫＰＩとか数値目標、アウトカムという形で、いろいろ区の事業も含めて入ってきておりますので、それを用いて評価なり見える化なりをしていきたいと考えています。","voiceIndex":66,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"全体としてはＰＤＣＡになっていると思うのです。チェックという部分で、監査委員からの補助金制度に対して、今、こんの委員がおっしゃったような見える化。議会、区民がきちんとチェックできる、見える、こういう指摘というのは過去になかったのですか。","respondent":"秋山財政課長","answer":"それが補助制度の計画、立案のところでも、監査の指摘事項、予算等も踏まえていくことになっておりますので、私の記憶している限りでは、補助金について、監査から具体的にどんな指摘があったかというのは、記憶がないと考えています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問","question":"私も、何年度の決算のときの監査の委員の意見で、こういう具体的なというのが今、手元にないので、参考までに、きっとあったということでお聞きしました。その上で増やすものは増やす、減らすものは減らす、見直すものは見直す、しっかりこういうＰＤＣＡをまた構築していただければということで、これは意見で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"}]},{"id":"topic-03","title":"平成２８年陳情第１１号 国土交通省の首都圏空港機能強化による羽田空港増便の環境と住民の健康への影響","agenda":"平成２８年陳情第１１号 国土交通省の首都圏空港機能強化による羽田空港増便の環境と住民の健康への影響","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"常々、我が会派からも、この飛行ルートについては、さまざま騒音や大気汚染、落下物、そして墜落の危険性も含めて、住民に多大な影響があるということで出していますけれども、やはりそういった影響をしっかり明らかにしてほしいというのが、今回のこの陳情の趣旨だと思います。加えて、場所がどこにあるのかも教えていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"一般測定局ですが、八潮につきましては、年平均値が１５.４となっておりまして、若干、基準に達していない状況です。日平均値３５ですけれども、こちらも３６.３となっておりまして、３５より若干、基準値に達していない状況になっております。","voiceIndex":79,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"八潮については、ＰＭ２.５については、年についても日についても満たしていないということでしたけれども、東京都の出している資料の中で、豊町の数値も出ている、測定局も出ているのですが、それはないのでしょうか。","respondent":"三ツ橋環境課長","answer":"こちらの一般測定局につきましても、ＰＭ２.５につきましては、年平均は１４.５で達成しているのですけれども、日平均につきましては、３５の基準のところが３６となっておりまして、若干、上がっておりますので、基準値には達成していない状況です。","voiceIndex":81,"id":"exchange-033"},{"speaker":"のだて委員","kind":"確認","question":"豊町のところは、場所についても教えていただければと思います。航空機からの大量の微粒子が排出されていることが確認されたという報告書も出ております。しかし、この間、質問の中でも聞いておりますけれども、答弁を聞いていると、品川区の影響は限定的だと言っております。区民への悪影響はないと考えていらっしゃるのか、伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"大気汚染につきまして、区の考え方ですけれども、答弁の中にもありましたように、環境省で出されておりますデータに基づきまして、航空機につきましては１５０の中の１ですので、ごくわずかであると。こちらは環境省のデータに基づいているものです。","voiceIndex":83,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"環境省の出しているものは、日本全国の中で航空機から出されているものがどれくらいかということだと思います。その１５０分の１というのは、飛行機が飛んでいないところも含めたものになっておりますので、限定的と言ってはいますけれども、本当にそうと言えるのか。区内での値の上昇というのはあり得ないのか、伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"したがいまして、ＰＭ２.５、また大気汚染につきましても、まずは、今、現状を測定している段階です。実際に、豊町、また八潮につきましても、ＰＭ２.５は測っておりまして、実際、基準値よりは高い状況にはありますが、引き続き注視している状況です。","voiceIndex":85,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"東京都からも、国に対して、ＰＭ２.５などの発生源の実態など、対策を早急に講じることですとか、健康影響などに関する正確な情報やデータを適切に提供することという要望が行われています。区としても、しっかり明らかにしていくべきだと思います。区としては、今、国交省から、実際的な影響が示されないもとで、明らかにしていく必要があると思いますけれども、いかがでしょうか。","respondent":"三ツ橋環境課長","answer":"大気汚染につきまして、例えば、今回の状況につきまして、騒音関係につきましては、実際に今までずっと国に要望しておりまして、測定を実施するということを勝ち取っています。","voiceIndex":87,"id":"exchange-036"},{"speaker":"のだて委員","kind":"確認","question":"実際に国が何をしていくか確認していくということなのですが、今、確認できているところはどういったことがあるのか、お話しいただければと思います。そして、やはり今回、新ルートを通ったことによって、値がどう変わるかということもしっかり想定していかなければならないと思うのですけれども、影響は限定的だというお話ですが、限定的であっても値は上昇するという認識なのか、区のお考えを伺います。","respondent":"三ツ橋環境課長","answer":"今回につきましては、飛行経路の変更という部分ですので、環境影響評価条例にもあたらないという返事はいただいております。","voiceIndex":89,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に対して、環境アセスメントをやるように求めているということでしょうか。そして、値が上昇するかどうかということもお聞きしましたので、お答えいただきたいと思います。","respondent":"三ツ橋環境課長","answer":"そのあたりにつきましても、１５０分の１という、わずかな航空機の中で、ＰＭ２.５ですと、粒子径はマイクログラムなのですけれども、そちらのデータがどのような値になっていくのか、値が上がるのかどうか、数値としてあらわれてくるのかどうかは。","voiceIndex":91,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"国にも、法に準じたアセスメントのものをできるかどうか確認しているということですので、ぜひ、しっかりやっていただくように、区からも強く言っていただきたいと思います。国がやらなかった場合は、区として、区民にどういった影響が出るのかというのを明らかにしていくべきだと思いますけれども、お考えを伺います。","respondent":"三ツ橋環境課長","answer":"しかしながら、例えば、何かの結果の場合に、できないという結果が出た場合、区がするかどうか。本来ならば、環境影響評価と申しますのは、こちらの資料にありますように、事業者自体が予測、調査、評価をするべきものです。","voiceIndex":93,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"アセスメントについては事業者が行うものだということなので、ぜひ、やるまで粘り強く求めていっていただきたいと思いますし、アセスメントでなくても、区民にどういった影響が出るのかということは、区としても明らかにしていくべきだと思いますので、そこも積極的に行っていくようにお願いしたいと思います。どういった中身になるのか伺いたいと思います。伺います。","respondent":"中村都市計画課長","answer":"それからあと、２つ目の質問ですけれども、防災計画の中で、航空機に関するものについて、どういった中身がですが、これは今、これから検討していくということになっているです。この中身がどうなるかも含めた検討を今後していくです。","voiceIndex":95,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、さまざま飛行機事故や重大トラブル、人命にかかわるところで、国内では１３件あったというお話でした。そういった中で、そういった墜落事故についても影響を考えていく必要があると思うのですけれども、今、防災計画についてはこれから検討ということでしたが、墜落の事故が発生した場合にも検討をして、防災計画に盛り込んでいっていただきたいと思いますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"危機管理というのはいろいろなジャンルがありますけれども、航空機につきまして、さまざまな可能な限りの予測の中で、できる限りの対応が中身に盛り込まれていくように検討してまいりたいと思います。","voiceIndex":97,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"新ルートが実施されることによって、区民に多大な影響がある。この影響をしっかり明らかにしていくべきだと思いますので、ぜひ、採択していただきたいと呼びかけて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのですが、例えば、国は五反田、品川駅、あるいは大井町、大井競馬場と、新ルートの高度や騒音というのを３カ所しか明らかにしていないのですけれども、ほぼ直下となる目黒駅や大崎駅、立会川駅、そして、特に心配の声が大きい八潮、この４カ所の高度と騒音です。お伺いしたいのは、品川区内でも、総排出量のうち飛行機の影響というのは１５０分の１なのでしょうか。そこら辺をお伺いします。","respondent":"三ツ橋環境課長","answer":"大体、五反田駅あたりが７５０メートルと聞いております。騒音につきましては、大井町が８０デシベルと国が言っておりますので、目黒駅は、それよりも音は少なくなると考えております。ＰＭ２.５の影響ですけれども、実際に、この１５０分の１というのは公なデータです。","voiceIndex":100,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"読売新聞で先日、１１月１６日夕刊でしたけれども、「２００９年度以降、８年間で航空機の部品脱落４３７件」という報道がありまして、事務局から、コピーで各会派に回ったと思うのですけれども、この脱落した部品とはどういったものだったのか、それが人に当たった場合どうなるのか、戸建住宅に当たった場合どうなるのか、伺います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"横引きとなりますけれども、区として、実際に普通の大気汚染を測定する場合には、こちらが航空機とか、こちらが実際に自動車からのものとか、ＰＭ２.５に色がついているわけでもなく、形が目立ってついているわけでもないので。委員ご指摘の被害を予見しないですけれども、航空機事故も含めて、落下物もあってはならないものだと思います。そういった中では、実際に落下物が何件あるとかは、予測は本当にできないところです。","voiceIndex":102,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"それと、大気汚染のところは１５０分の１、環境省のこの生データを否定するつもりはないのですけれども、これは日本全国での平均値、実態を示しているだけであって、これが特に臨海部、そして、これから航空機が新ルートで通っていくという品川区においては、やはり１５０分の１とは違ってくるだろうと申し上げましたので、それでもあくまで同じだと言い張るのか、そこら辺はもう一回。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"したがいまして、例えば主要駅、今回ですと大井町駅が基準になると思うのですけれども、両方のＡ滑走路部分、Ｃ滑走路部分、それぞれの駅がありますので、例えば、今申し上げましたように、大井町駅ですとこのぐらいの値、また。こういった部品、落下したものが人に当たったときの影響というのは、これは申し訳ありませんが、被害はあるだろうと思いますけれども、ただ、それがどの程度かというのは予測は私からは申し上げられません。","voiceIndex":105,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、海上足下げができない都心ルートということになりますので、落下物のリスクはもっと高まると思うのですけれども、リスクが高まるかどうか、品川区の見解をお伺いします。人口密度という点で、成田空港と羽田空港のルートではかなり違うと思うのですけれども、どれぐらいの違いがあるとお考えなのか、あわせてお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"足下げと落下物の関係ですけれども、こういった落下物につながるような飛行のアクションについては十分注意していただかなければいけないと。ただ、一方では、国のまたある説明では、足下げが落下物に直接起因していないという最近のデータがあるというようなことも言っています。","voiceIndex":108,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"再三、足下げと落下物の因果関係がないという国の説明がされるという答弁もあるのですが、最近の１１月２４日の国土交通委員会の中でも、我が党議員の質問に対して、「成田空港では、かつて、もっと多かったのが減少したのだけれども、何が理由でしょうか、お答えください」というところで、参考人の方が政府の答弁として、「機体整備の徹底を図ることが重要だと同時に。","respondent":"中村都市計画課長","answer":"この駐機中の点検につきましては、今度、新たに制度として取り入れようと国として考えているという説明を受けております。その頻度、あるいは、どういった部分を点検するのか、こういったものについては、現在は聞いておりません。","voiceIndex":110,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"驚くべき答弁だったのです。それとあわせて、騒音の問題についても、重要な問題ですので伺います。基準内だった。例えば、Ａ滑走路ルート下の大井町でいうと、８０デシベルの騒音が１時間に４分に１機の頻度で飛来しまして、それが３時間続く、こういう日が、年間４割ですので、１４６日、受け続けるということになるのですけれども、こうしたことでの健康被害はないのか、あるのか、伺いたいと思います。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"今後、新たな原因の追求ですとか、あるいはアイデアが出てきたり、あるいは新技術が出てきたりすれば、また新たな効果的な点検方法も出てくるかと思いますので。４発機のジェットエンジンが今はほとんどなくなりまして、２発機エンジンになっている。そこの部分が大きいこと。沖合展開があったことによって騒音の影響はかなり低くなっている状況にあります。","voiceIndex":112,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"その前は、２４時間でならすという考え方はなかったものから、そうしたものにかわったのかどうか。そこら辺を明確にお伺いしたいというのが１点です。この点については、２点お伺いしますが、江戸川区でも新宿区でもやって、どうして最も被害が大きい自治体の１つである、この品川区ではやらないのか伺いたいと思います。どうしたら品川区内で教室型説明会が実現するのか、区のお考えを伺います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"しかしながら、平成２５年４月より新基準に変わりまして、新基準、Ｌｄｅｎですけれども、地域累計が５７、また、地域累計が２の部分につきましてはＬｄｅｎ６２となっております。こちらは平成２５年４月より新基準に変わっております。やはり区としては、かねてから教室型説明会を求めているものですので、それは委員がご指摘のとおり、また、区の考えも教室型をやっていただきたいというのは強い願いですので、引き続き求めてまいります。","voiceIndex":115,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"教室型説明会のところに関しては、ある意味、健全な地元自治体としての怒りも持っていただいて、先ほどの他区の例などもぜひ紹介しながら、国に強く求めていっていただきたいと思います。ここについてお伺いしたいと思います。それと、基準が変わったというのは、平成２５年４月以前には、特にそういった動きがなかったのか。そこについてもお伺いします。","respondent":"三ツ橋環境課長","answer":"基準が少なくなったから過小評価をするというのは、それは異なっておりまして、実際にきちんと国際基準にのっとった評価ですので、過大評価、過小評価という観点ではございません。","voiceIndex":118,"id":"exchange-050"},{"speaker":"筒井委員","kind":"質問","question":"この新ルート案で、足下げの位置は大体どこになるのかということはご存じなのでしょうか。","respondent":"中村都市計画課長","answer":"この飛行経路案、こちらはあくまで案ということで、まだ具体的な足下げの位置ですとか、そういったものは国として具体的な説明を受けておりません。というのも、まだ決定をしていないのだろうと考えております。","voiceIndex":120,"id":"exchange-051"},{"speaker":"筒井委員","kind":"確認","question":"大体、先ほどご答弁された主要駅の高度とか騒音というのもわかっておられるので、おそらく足下げをするという位置も、技術的には大体わかると思いますので、その点のご確認をお願いしたいのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"私も、そこら辺の専門技術的なところはよく存じ上げません。ただ、一定程度の範囲で、ここからこのぐらいの間に足を下げるとか、そういったものはある程度は推測できると思いますので、そういったものを国に対して求めてまいります。","voiceIndex":122,"id":"exchange-052"},{"speaker":"あべ委員","kind":"質問","question":"本日の陳情審査、環境ならびに健康調査ということが陳情項目となっておりますので、それに沿ってお伺いしたいと思います。冒頭で八潮を含む品川での環境調査の調査結果をお伺いしました。品川区の今の大気の環境と状況というのはどのように区として捉えていらっしゃいますでしょうか。実際に２３区内で極めて高い値と言えるのでしょうか。教えてください。","respondent":"三ツ橋環境課長","answer":"その部分の中で、国や東京都に対しても、やはり大気汚染につきましては広域的なことだと考えておりますので、例えば常時監視をしていく、また、道路の要請限度なども監視しておりますので、引き続き、そちらとあわせて申し入れていきたいと考えています。","voiceIndex":124,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問","question":"把握している限りで、２３区の中で品川区、あるいは八潮地域の大気汚染がどのようなレベルにあるのかということ。先ほどお伺いしたのですけれども、今、お答えをいただければと思います。その結果の、この数字だと考えているのですが、ざっくりでいいのですけれども、それぞれの排出における寄与率、構成割合というのはどのように考えていらっしゃいますでしょうか。","respondent":"三ツ橋環境課長","answer":"寄与率ですが、大井中央陸橋はやはり大型のトラックがあるという部分が非常に大きいと考えております。しかしながら、パーセンテージで出すことができないのですけれども、船舶の影響や、また、大きなトラックの影響等を考えております。","voiceIndex":126,"id":"exchange-054"},{"speaker":"あべ委員","kind":"質問","question":"それで、そのときに、実際に飛行ルートがより内陸に入ってくるというのはマイナス要因の大きな１つだと考えています。工業地帯の周辺などでは、どういう由来で大気汚染があるかというのはデータとして推計値が出ているわけですから、技術的に不可能ということはないと思います。現状、何をしているのかということと、どんな働きかけをしているかということを教えてください。","respondent":"三ツ橋環境課長","answer":"実際、広域的な部分もありますので、区独自で取り組むのが非常に難しい部分ですが、東京都に対しては、いろいろな話し合いの中で、この現状について品川区として何をするべきか、また、東京都が何をするべきか。","voiceIndex":128,"id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"この航空機の問題で、八潮の大気汚染の問題も注目を浴びたわけですけれども、全体として削減をしていくということは、ぜひ区として取り組んでいただきたいと思います。環境にかかわる健康の問題については、どのように捉えていらっしゃるのでしょうか。これだけ恒常的に大気汚染がということになると、例えば呼吸器系の疾患などが多いという現状もあるのでしょうか。","respondent":"三ツ橋環境課長","answer":"実際にＰＭ２.５の測定局を設置するにあたっても、八潮に測定局を設置することができたのは、やはり東京都も広域的にこの場所がいいと考えて、ＰＭ２.５の設置もしている状況にありますので、引き続き、大気汚染に関しては東京都に申し入れをして、また。","voiceIndex":130,"id":"exchange-056"},{"speaker":"あべ委員","kind":"質問・要望","question":"現在の健康状態と、それから、そこに変化があらわれるかどうかというのは、若干、所管違いにはなりますけれども、ぜひ、区でも把握できるようにしておいていただきたいと思うのですが、いかがでしょうか。ご答弁できますか。","respondent":"三ツ橋環境課長","answer":"実際に、３時から７時の間に飛行機が通るということで、国がどの程度の健康被害を考えているのか。そのあたりにつきましても、国に対して確認してまいります。","voiceIndex":132,"id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"調査をするということは、変化があったということがわかる、あるいは、なかったということがわかる。あったとして、どの程度だということがわかる。それ以前の問題として、まずは現状よりも、より少ない環境負荷にしていくという、さまざまな努力、対策というのは、ぜひとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-058"},{"speaker":"新妻委員","kind":"質問・要望","question":"長時間にわたってのこの質疑の中で、さまざまなことが確認をされました。ここは改善を求めていく必要があると思います。今まで、都や国に対して申し入れをしていくという課長からのご答弁をいただいておりますが、現状の改善を含めて、さらにしっかりと調査、データ、正しい数値に対してどう影響があるのかということも含めて、また東京都なり国なりに求めていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"そちらにつきましては、区としてしっかりと、東京都、また国に対してするべきことを、広域的にわたって、実際にしなければならないことがたくさんあると思いますので、きちんと申し入れてまいります。","voiceIndex":135,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"新ルートによってどういった影響が出るのかということを明らかにしてほしいということですので、区としても、まだ説明は不十分だと言っているものもありますし、しっかり明らかにしていくことが必要だと思いますので、結論を出すということで、採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-060"},{"speaker":"あべ委員","kind":"質問・要望","question":"一連の継続となっている羽田空港関連の陳情、請願と一体のものとして継続としたいと思います。ただ、今回の陳情につきましては、環境問題に特に焦点を当てているということで、先ほども申しましたが、この地域的な環境の問題のデータですとか要望というのは、それはもう粛々と進めていただきたいと思います。それを添えまして、この陳情については継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じように、現在、この新ルートによって影響がどうなるかということですので、結論を出すということで、採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":54625,"voices":156}},{"id":"h28-20161201-18","meetingId":"h28-cm12","date":"2016年12月1日","dateIso":"2016-12-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"幾つか段差があったり、それからあとは車いすで通りにくいところもたくさんあるし、それから首都高速道路の下のところを通っていくわけですから、そこのところのコースの安全対策等も検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"お願いベースの話でありますけれども、お願いをしてどういう反応なのかというところをお伺いしたいというところと、４７番についてはうちの会派から出させていただいたのですけれども、この「バリアフリーで鑑賞できる環境整備について」というのが、果たしてこれは品川区が関与できることなのかということも含めて、都にお願いするということはもちろんそうだと思うのですが。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"ただ、この立会川駅に限りましては、オリンピック・パラリンピックに合わせまして、期限を切った形で可能な限りのところで実施していただくようにお願いはかねてからしているところでございまして、ただこれも鉄道事業者からは。４７番の「競技・文化プログラム等をバリアフリーで鑑賞できる環境整備について…」ですが、施設の、例えば区立施設であるとか、都立施設であるとか、そういった主体によって違ってくるかとは思いますけれども。","voiceIndex":5,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"駅のバリアフリー化についてですけれども、今推し進めていただいてる、先週も大井競馬場についてはかなりいいお返事をいただいているということも今伺って、事業者によって、また駅によって温度差はあるかと思うのですけれども、やはりこの契機を逃すと非常に難しいものがあるのかなと思いますので、何度も何度もお願いをしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私からちょっと１点お伺いをさせていただきたいのが、バリアフリーと一言で言っても、例えば世界的な基準があったり、日本の基準があったり、あとはオリンピック・パラリンピックの大会組織委員会の中での基準があるのかどうなのか、まずその辺をお聞かせいただければと思います。","respondent":"多並道路課長","answer":"その場合は、今もう公表されていますけれども、Ｔｏｋｙｏ２０２０アクセシビリティ・ガイドラインというのがありまして、実は、そちらのほうで検討しておりまして、それに向けてまずはハード整備、会場であったり、工事でやはり時間がかかりますから。","voiceIndex":9,"id":"exchange-004"},{"speaker":"いながわ委員","kind":"提案","question":"そこはバリアフリーをするといったらフラットにしなければいけないとなると、今度は下を船が通らなくなってしまいますから、そういう部分も含めた中で、提案としてはそういうところに、例えば車いすを押すボランティアを配置したりというのは、区のほうで可能なのかどうなのかというところは、提案と可能かどうかというのを教えていただきたいと思います。","respondent":"多並道路課長、中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"それでこれから、今国と都と区で、大会の会場がある区で、特にバリアフリーについてはアクセシブルルートという形で、誰でもご利用しやすい環境を整える。急勾配となるようなところも、これも工夫によって、可能な限りそういったところはないようにするというのが基本的な考え方ですが、ただ。委員が危惧されている場所については、恐らく東京都が配置をする予定になっております都市ボランティアが対応するのではないかと思われるのですけれども。","voiceIndex":11,"id":"exchange-005"},{"speaker":"いながわ委員","kind":"提案","question":"それぞれ答弁ありがとうあります。ぜひ品川区がバリアフリーに関して、いや、こうなのだからこうしてくれという思いが、もちろんこのオリンピック・パラリンピックの推進特別委員会で出された案や提案も含めた中で、しっかりと国や東京都に、何というのでしょう、提案をしてそれを実現していくような形でお願いをしたいと思います。","respondent":"中村都市計画課長","answer":"しかしながら、そういった区民の皆様からの要望はしっかりお伝えをしてありますので、鉄道事業者からはその辺は念頭に置いて、今後また検討していきたいというような回答を得ておりますが、ただ早急に改善されるかどうか、ここは区は引き続き。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"潮風公園のことをちょっと今思い出したのですけれども、ここのバリアフリー、当然品川区の直接の管理ではないのですが、これも当然品川区内のことなので確認をお願いしたいと思います。それからまとめでいくと、今委員長は交通のことは別とおっしゃったけれども、でもここのアクセスを考えていくと、今現状は車しかないわけで、だからどうするのだということが出てくるわけですよね。お願いいたします。","respondent":"多並道路課長","answer":"今の潮風公園の周りの件ですけれども、実は先ほどちょっとお話しさせていただきましたアクセシブルルートの観点で、潮風公園の周辺についても、今ちょうど検討しているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そこで品川区の意見はどれだけ取り込むことができるのでしょうか。なかなかアクセスのことについては、電車を通すとか、そういう大きな話になるとなかなか難しいのかもしれないけれども、でも今言ったアクセシブルルートの基準に基づいて展開しているのであれば、ぜひ品川区の意見を相当盛り込んでいただくようにお願いしたいのですが、それは可能性ありますでしょうか。","respondent":"多並道路課長","answer":"その会議体としては、今回ホッケー場の周辺も関係ありますので、そういう関係で我々品川区も入る予定だと思います。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問","question":"このバリアフリーというところで、京急の新馬場駅の名前等も出ているのですけれども、そのほかの駅、やはり羽田から直通で向かえるということで、京急が便利に使えると思うのですが、先日の決算特別委員会でも、この京急のホームドアの設置、ここが全く計画がないというか、東急などは２０２０年までに全駅にというふうなことだということですけれども、京急のほうは全く。","respondent":"中村都市計画課長、中山障害者福祉課長、多並道路課長","answer":"今、京浜急行のほうでは、この駅の京急各駅の耐震化を進めるのがまず優先事業として進めているところは聞いておりますけれども、ホームドアについては。その結果、もちろん手話の配置であったり、あるいは音声で視覚障害の方にはＦＭ電波を使った音声での案内であるとか、あるいは車いすの方であれば。ただ、実際には和式のものを洋式にするのは、実はそんなに簡単ではなくて。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで京急のホームドアの件ですけれども、耐震化が優先と、そこも大事ですが、一緒にやはり進めていかないと、本当にもう２０２０年、間近ですので、進めていっていただかないと、もしもオリンピック・パラリンピックの際にこちらに、品川区内に来られた方が、ホームに転落などということがあったら本当に大変なことですので、ぜひ強力に、こちらからも要請をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっと意味を取り違えていたら申しわけないのですけれども、ボランティアの方の重要性とともに、積極的な支援、要するに一般の方の支援ということを求めていたのかなというふうに私は感じていたのですが、先ほどのボランティアの方の支援ということで、課長からもご答弁いただいたと思うのですけれども、こういう、どうしてもバリアフリーにし切れない部分をどのようにフォローしていくのかというのが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういったことを区も先駆的に実施をする中で、区民全体が皆さんをおもてなしするような機運を高めていけるように、今後も区としては考えてまいりたいと思っています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ一般の方というと変かな、障害を持った方よりも、今のお話だと観光客というか、お見えになる方に対しての意識というのが強い感じも、ちょっと私も感じてしまったのですけれども、もう少し障害の方に対するふだんからの我々の接し方もあると思うのですが、そこら辺が、自分でもどう接したらいいかわからない部分が非常にあると思うので、その辺を区として。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば区のほうでも、スポーツ推進委員を対象にユニバーサルマナー研修を実施したりですとか、また区の新人職員を対象にユニバーサルマナー研修をし、実際に車いすに乗られている方を講師にお迎えして。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。いろいろやっていただいているのは十分わかりましたので、これからもぜひお願いしたいのと同時に、私たちもブラインドサッカーを体験して、本当に目が見えない状況というのはこんなに厳しいかなというのを感じたところもありますので、これからもその辺力強くやっていただきたいなということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"だからコーツ副会長も、１兆円を切ってやってくれみたいな、次回のオリンピック・パラリンピックに名乗ってくれる都市がなくなってしまうのは困るから、余りお金をかけないようにやってくれというふうにくぎを刺したのは当然だと思うのですけれども、だからこそいろいろな関係機関のところで、そういう施設整備にはロンドンでは７,４８４億円を上限にしたという話なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、考え方として、例えば品川区の単独の独自財源を使わない、東京都なり、そういうところでやらなければいけない部分の改修なり、公費を使うという部分について、ボトムアップで品川区としてはここは必要だよね、だけれどもこれは品川区の単費ではないよねというところの、そういう仕分けが当然されていくわけですけれども、そういうものを東京都なりに上げていく。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それはそれぞれの、東京都のほうでお考えになって、区にこういうことをやってほしいということで補助金の情報が来て、区といたしましてはできるだけ補助金を活用してという考え方があります。","voiceIndex":36,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"だけれども、今はそれがない中で、東京都から来るお金ということで例えば機運醸成だとか、無電柱化のところの紹介があったのですけれども、それがトータルで数年たったら、やはり予定額よりオーバーしてしまったというようなことになってはならないと思うので、やはりきちんとした構成を考えて、そこを先に打ち出して対応していくことが必要なのではないかと思っているので、その辺についての考え方。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"全体の経費に関しましては、先ほども申し上げましたが、国、東京都、大会組織委員会がそれぞれの責任のもとにおいてきちんと管理をしていくべき問題であると考えております。","voiceIndex":38,"id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"すみません。もし可能でありましたら、この委員会の中でも、例えばそういう研修、そういう講座をどれか、ブラインドサッカーの体験教室はもうやりましたから、こういうものをこの委員会の中で１回体験してみて、それで議会全体とか、それから区民に広げていくというような議論をそこから起こすというようなことはいかがでしょうかという、これはちょっと提案させていただきたいと思います。","respondent":"中村都市計画課長","answer":"しかし、今現在は区としては、まずは計画がない事業者には当然計画を設定してくださいとお願いをしておりますが、また今後積極的にホーム柵を順次、１年置きに計画を立てていきたいと、そういった相談がある事業者につきましては、まず区としては。","voiceIndex":40,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。もちろん予算全体のこともありますし、恐らく鉄道事業者、いろいろな区を走っているわけだから、ほかの区からだって当然この要望は来るわけで、そこをやはり補助金という形で促す計画というのですか、そういうものをぜひ持っていっていただきたいなというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"大井競馬場前駅から大井ふ頭中央海浜公園までに通ずる無電柱化、地中化についてお伺いしたいと思うのですけれども、今あそこ、勝島橋の橋桁の補強工事をやっておると思うのですが、今私の知る限り、無電柱化は大井ふ頭中央海浜公園の前と大井競馬場の前、ところどころやっていると思うのですけれども、継続的に何か今、当然いろいろ調整しながら工事をやっていると思うのですが。","respondent":"多並道路課長","answer":"今後につきましては、来年度予定しているのが引き込み連携管といいまして、そこの地中化したものから、今度はわきの、競馬場であったり、大会会場であるほうへ向かう、引き込んでいくほうのＮＴＴであったり、東京電力のほうの埋設管工事のほうに。","voiceIndex":44,"id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、今塗装工事、大がかりに足場を立ててやっていると思うのですけれども、いずれこの橋自体、先ほどもほかの委員からもそういった橋に関しての説明がありましたが、これから整備をしていくという中で、例えば、これは歩道を含めた工事になると思うのですけれども、バリアフリーの工事もそうなのですが、そうすると、橋自体をまた手直しするとかについては。","respondent":"多並道路課長","answer":"ただ、橋から連続しまして、先ほどちょっとお話があったのですけれども、スロープにちょうどなっているところが特に競馬場の方向にあるのですが、橋からちょうど大井競馬場前駅を通過しまして、競馬場の交差点に向かってずっとなだらかにスロープがあるのですけれども。","voiceIndex":46,"id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、これはバリアフリーもそうなのですけれども、今道路の無電柱化、地中化をやっている中で、道路を含めて歩道なども大井ふ頭中央海浜公園の周辺は植栽が、今現在だと何か景観上はよくないということで、今後区として美観、景観を含めた整備を、例えば、何というのですか、花壇が続いていたりとか、要するに会場に向かうまでの障害者、一般の方も含めた人たちに対して、本当に歩道を歩きやすい道路。","respondent":"多並道路課長","answer":"実際これを整備する中で、品川区と大田区と１本の道路になっているところもありますので、やはりそれが一緒に連携するべきだろうということで、実は今一緒にどういうデザインにするかということで協議しているところです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"お伺いしたいのは、バリアフリー整備（会場へのアクセシビリティ）という形で括弧書きをしておりますが、改めてお伺いしますが、今のオリンピックの品川区内の、会場問題はどうなっているのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今、東京２０２０大会の品川区内で予定されている会場は、潮風公園でビーチバレーボール、大井ふ頭中央海浜公園でホッケーの２競技が会場として予定されているです。","voiceIndex":50,"id":"exchange-022"},{"speaker":"藤原委員","kind":"確認","question":"続けてですけれども、今年度中にその整備をする会議が立ち上がるという話をいただきました。確認なのですけれども、その会議に先ほどの答弁では品川区から理事者が入るように思えたのですけれども、それでよろしいのでしょうか。","respondent":"多並道路課長","answer":"今、国のほうが平成２８年５月３０日付で、「２０２０年東京オリンピック・パラリンピック競技大会に向けた道路のバリアフリー化を推進します」という発表をしておりまして、その中で、東京都がもともと策定した推進計画、バリアフリーの推進計画があるのですけれども。","voiceIndex":52,"id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"区の部長級が入られるということで、この特別委員会の中でもいろいろな委員から、また決算特別委員会等でも、バリアフリーに関してはいろいろなご意見が出たり、要望が出ていると思うのですけれども、そういう形であるならば、もう具体的にどことどことか、そういう形で国および東京都にリクエストを上げていく一覧表といいますか、そういう形で所管としては計画を立てているのでしょうか。","respondent":"多並道路課長","answer":"それ以外の細かい整備内容等については来年度以降の実施設計で決めていきますので、そのときに実際やる東京都の部署だったり、大田区だったり、東京モノレールだったり、そういう部署ともう少し密接に。","voiceIndex":54,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう今日から、今年も１２月なので、時がたつのは早いなという思いがありますので、来年が２０１７年ですから、もうあと３年ですから、計画的にやっていただきたいと思うのと、あと今日バリアフリーの整備という形ですけれども、１つ心配まではいかないのですが、２０２０年のオリンピック・パラリンピックに向けてのバリアフリーだけではなくて。","respondent":"多並道路課長","answer":"今回の面的な整備を進める際にも、やはり今後の、オリンピック・パラリンピックはもちろんその契機になりますが、それ以外の、それ以降もレガシーで残るようにということで、連携をしながら整備をしていきたいということが大きな目的でもありますので、区としても一体的に。","voiceIndex":56,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで要望項目の４６、４８とか、あとモノレールのお話とか、今日出たのですけれども、たしか京急やモノレールなどは、文化観光課でやられている観光事業に関して協議会をつくりましたよね。","respondent":"鈴木文化観光課長","answer":"ご指摘のとおり、今年度立ち上げました品川区観光振興協議会のほうのメンバーに入っていただいております。その中でさまざまな事業実施に向けた協力や、ＰＲの協力をいただいているという意味では、非常に良好な関係で連携をしております。","voiceIndex":58,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"それと、先ほど冒頭のほうでいながわ委員のほうから基準等の話がありましたけれども、今直近でもそういう確認もありましたが、これは区としてのそういうバリアフリーにしていく必要性があるところの洗い出しというのは、この２０２０年のオリンピック・パラリンピックに向けての会場周辺等を含めて、また先ほど来ずっとあるような大井町周辺だ、関係するアクセスで人が集中するであろう部分のところも含めて。","respondent":"多並道路課長","answer":"その周辺のバリアフリーを面的に進めていきたいということで、今ありまして、区としましてもやはり、区単独というよりは、やはり国と都と区と連携しながら、よりいろいろな方がお使いいただけるような整備を進めていきたいという考えもありますので。","voiceIndex":60,"id":"exchange-027"},{"speaker":"つる委員","kind":"確認","question":"基準とかをつくったのは、国だとか、都とかが、誰にどこに聞いてとか、そういういろいろな考え方などの中で、いわゆる基準はつくったけれども、実際の、何というのでしょう、実生活も含めた、そういう中での改善すべき点というのは、逆に言うと品川区の中の、まさに障害をお持ちの方々で実際に生活されている方々からしっかりと確認をしていくという作業も必要なのだろうと思うのですが、通常。","respondent":"多並道路課長","answer":"このように今後も、特に今度の重点整備をやるときには一緒に連携しながら整備を進めていきたいというのが考え方です。","voiceIndex":62,"id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"通常のそういう区役所だとか、公共施設への情報提供というだけではなくて、今回のバリアフリー整備だとか、アクセシビリティというところでは、オリンピックの競技開催会場へ向けての、そういう情報提供ということも、世界の方々が来られるわけですから、事前にそういった安心感を持って会場に来ていただけるというところでは、Ｙｏｕ Ｔｕｂｅ等を活用して。","respondent":"中山障害者福祉課長","answer":"ですから、どういった情報が一番障害のある方が安心して、ある地点からある地点への移動のときにどういう情報がふさわしいかということも研究しながら、オリンピック・パラリンピックに向けての課題解決に向けていければと考えているところです。","voiceIndex":64,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問・要望","question":"だからそういったものもしっかりと活用しながら、区としてしっかりと、そういう障害を持たれている方も、バリアフリーを必要とされる方も安心して来られるためには、事前にそういう動画で視覚的にもわかるような情報の提供というのが、絶対的に必要かと思いますので、広報広聴課だけはなくて、障害者福祉課またはオリンピック・パラリンピックの推進をする部門としても、そうしたところをしっかりと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-030"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは大井競馬場前駅のバリアフリー化について質問と、要望も含めてしたいと思います。大井競馬場前駅の改修工事をされるのかということで、もちろん駅自体も下のほうが鉄なのか、ちょっとわからないのですけれども、耐震のほうも危ないのではないかという危険性があると思うのですが、そういった話も出ているのか伺いたいと思います。","respondent":"多並道路課長","answer":"今のそこの駅をおりたところの歩道については、確かにこの基準は満たしているところなのですけれども、よりよい使い方ができるようにということで、今駅をおりた方がすぐ階段をおりるようになっていますので、それを改善できないかということで、これについても。","voiceIndex":67,"id":"exchange-031"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に要望ですけれども、もしできるのであれば、その駅から階段のほうではなく、直接橋につながる出入り口を設けていただきたいなと思うのです。例えばそこでも、先ほどもエレベーターで下まで行かないといけないというのもあったので、ではそのまま直接会場に向かえるスロープのようなものをつくっていただければ、そのまま会場のほうに向かえるのではないかと思いますので、要望としてします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これがオリンピック・パラリンピックが終わってから、これはオリンピック・パラリンピックのためにやっていたのだよと、４年後以降そういう話になってしまうと、それはちょっと違う話なので、１回ちょっと改めてそこの確認だけを、何か共通の問題意識として捉えて、今後私たちも積極的に要望していってよろしいのかどうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"実際にボランティアの部分で、では品川区というのは何を、先ほどおっしゃったように品川区の区民の方、スポーツ推進委員の方々とか、いろいろなボランティアをやりたい方がいらっしゃると思うのですけれども、その人たちがやはり介助するとか、もちろん地元の方ですし、非常にやる側としてはそういうものに参画したいという思いもあるのですが、これ現実問題として。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうしたときに、区としてまさに大会期間中にどういったボランティアが必要なのか、例えばリオで見てきた、清掃が行き届いていたというようなところで、品川区の中で清掃ボランティアというものを養成したほうがいいのか、あるいは今観光ボランティアもいますけれども。","voiceIndex":72,"id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"日本人相手であれば、アプリをダウンロードしてくださいで済むかと思うのですけれども、殊さらオリンピック・パラリンピックでは、多分外国人が多く来るのではないかなと思って、その辺をまず行政としてどういう視点で考えられているかというのをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところを大きくフューチャーするというのも１つ、これはありますし、先ほど申しましたように日本で開かれるということであれば、そのアプリをどのぐらいやるかどうかというのは、これは考え方として検討しなければいけないというのはありますけれども。","voiceIndex":74,"id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひその辺は、ターゲットを絞るという言い方はおかしいと思うのですけれども、世界各国の方、日本人も含めて来訪された方といいますか、いらした方で、行く行くは都市型観光を考えれば、来訪客というのですか、その人たちにとって有益な、しっかり実効性の担保というと言い方はおかしいですけれども、利用できる、そういったサイトというのですか、をしっかりつくっていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺をどのように判断していいのか、ちょっと考え方をお聞きしたいと思うのですけれども。","respondent":"多並道路課長","answer":"ただ、実際あそこの周辺で、どこかおりられる場所がないかですとか、あとは１日ほとんどとまらないバス停が、バスが走っているところがあるのですけれども、そういうところとか、周辺でももしかしたらいろいろな部分があるかもしれませんので、それも含めて。","voiceIndex":77,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"意見","question":"本当に難しいなと思って。ただ、それと同時に障害者の方がどの程度あそこを使う方がいるかどうかも、はっきり数字はわからないですけれども、やはりそのときに非常に感じて、これは大変だなというのをちょっと思ったので、何かいい方法をこれからも検討して、探っていってくださいとしか言いようがないと思うので、その辺よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-038"},{"speaker":"伊藤委員","kind":"確認","question":"そういうのを掲げていくことを伺ったので、そのことはされるのでしょうけれども確認をお願いするのと、それから会場内のピクトグラムサイン等々の内容とか、それから障害者等の車いすの民間貸し出しなどやっているという報告がありましたので、そのことの確認で、ＳＮＳの話がちらちら出てきましたが、恐らく２０２０年はもっと進化すると思います。","respondent":"小川オリンピック・パラリンピック準備課長、鈴木文化観光課長","answer":"区としては、区独自でサイン類に関しては今年度新たな計画もできて、いろいろな各所管で対応しているところではありますけれども、それはそれとして、大会期間中にまさにどういったサインがあり。その情報をもとに、オリンピック・パラリンピックに際して適切な活用の方法、また言語の表示等もアレンジをすることで十分対応できると思いますので、そこはうまく連携をしながら。","voiceIndex":80,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと２巡目で申しわけないのですが、今の、ちょっと私も質問しようと思ったところを伊藤委員のほうで質問していただいたのですけれども、現に今、既に外国の方がアクセシビリティで困難を感じているというところでちょっとご相談いただいていたので、これは都市開発課のほうにも１回お願いをしたことがあるのですが、現状教えていただきたいのですけれども。","respondent":"鈴木文化観光課長","answer":"区としましては、観光の面でも、それからオリンピック・パラリンピックで訪れた方、または障害のある方、ない方含めて、その辺の案内サインは、例えば建物の所有者、それから道路管理者、それから事業の実施者、それぞれで連携をして。","voiceIndex":84,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今そういうふうにしていただいているかと思うのですけれども、やはりスピード感は大事だと思うのですね。この点について、オリンピック・パラリンピックを待つ、その直前まで待つというのか、それともできるだけ早く、アズ・スーン・アズ・ポッシブルでやっていただけるのか、ここについてを最後確認させていただきたいと思います。","respondent":"鈴木文化観光課長","answer":"しかしそれだけが整備の効果が活かせるものではありませんので、できるだけ早く、ただし、相手のあることもありますので、その辺の調整をスムーズにすることも含めて取り組みたいというふうに考えております。","voiceIndex":86,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ会場周辺には、組織委員会なり、東京都がボランティアを配置するわけですよね。まだ３年、４年あるわけなので、どのように会場の中での運営がされるのかというのは全然雲をつかむような思いで、勝手な解釈をしてイメージを持っているのですけれども、その辺というのは大体どんなふうになっていくのかも含めて、ちょっと伺って、ぜひこのシャトルバスも含めて検討していただきたいと思っています。","respondent":"中村都市計画課長、小川オリンピック・パラリンピック準備課長","answer":"これにはまず、大会の開催される当日の輸送につきましては、選手などが優先レーンを使って会場まで高速道路や一般道を使ってくるというようなところもあって、そういったところでは緻密な計画が今、時間におくれてはいけませんので。ボランティアのご質問がありましたので、お答えいたします。リオでの経験なのですけれども、報告書の２７ページを見ていただきたいと思います。","voiceIndex":88,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"今のボランティアの件からいきますけれども、私がイメージしていたのは、健常者はそういうことで十分いいと思うのですね。したがって、そういうことも含めて、品川区がするべきなのか、東京都がするのか、それぞれのやるべきセクションがあって仕分けされていくと思うのですけれども、そういう段階でもぜひちょっと検討もしていただきたいということを要望としてお伝えしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-043"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいんですけれども、まずこの１０月２９日に開催されたユニバーサルスポーツ大会ですけれども、何種目開催されたのかということを１点お伺いします。とにかくやはり品川区に行けば障害者スポーツが盛んだというのを、都内のみならず全国に発信できる体制をとっていただきたいと思いますが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"１０月２９日のユニバーサルスポーツ大会ですけれども、やった種目を並べします。","voiceIndex":96,"id":"exchange-044"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、品川区は始めたばかりというか、近年非常に多くやっているので、その中にそういうのも入れていっていただきたいという、もちろん車椅子バスケットボールもいろいろ体育館の構造上という部分もあるかもしれないのですけれども、それはもちろん大切ですし、幅広い障害をお持ちの方が一緒に楽しめるスポーツを実現していただきたいと思うということで質問しましたので、よろしくお願いします。","respondent":"池田スポーツ推進課長","answer":"ただいまの知的障害者のスポーツ教室ですけれども、今、第２・第４土曜日に体育館でそれぞれ障害者スポーツ教室を行っているところですけれども、この部分については、場所が大崎と戸越ということで偏っているですので、ちょっとこれから区内全域とまではいきませんけれども。","voiceIndex":100,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"それで、当日もちょっと質問させていただいたのですけれども、目の見えない方にサッカーってこのように楽しいものだよということを教える教室があるのかどうかと、今後の推進ということで言えば、そういうようなことをそういう団体と一緒に模索するということを品川区として考えていらっしゃるのか、その辺について伺いたいと思います。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"私どものほうでは、２のその他ところで書いてありますように、日本ブラインドサッカー協会が現在荏原第六中学校を使って練習をされているということで、こちらで荏原第六中学校の生徒さん、もしくは地域の方と。そういった情報は区としてもキャッチしておりまして、日本ブラインドサッカー協会とはパートナーシップ協定も締結をしておりますので、今後場所の提供ですとかいろいろな面で、区としてできることは連携していきたいと考えています。","voiceIndex":102,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときにすごく私も気づかされたのですけれども、やはり体を動かす楽しさを体験する機会がなかなかないという障害当事者の方たちもたくさんいらっしゃると思うので、ぜひ品川区としても、今、参加している方だけではなくて、新しいスポーツに触れるような機会を、それは健常者も障害者も関係なく、こういう機会というものを検討していっていただきたいと思います。これは要望でとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご説明ありがとうございました。地域のグラウンド・ゴルフの愛好者のクラブの方たちが、審判をやったりいろいろご協力いただいた中で、これは今は、みんなでグラウンド・ゴルフというのはここだけですけれども、今後について、そういったグラウンド・ゴルフのこういった会をもっと品川区として開催していくのかどうかをお聞きしたいのが１点です。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"こちらのグラウンド・ゴルフのほうですけれども、確かに現在旗台小学校で行っているグラウンド・ゴルフにつきましては前半と後半ということで２回に分かれてやっているということで。町会ですとか自治会ですとかも、１０人以上の人数が参加して、またなおかつ場所があれば、いくらでもこちらのほうで区が提供しますので、もしそのようなご紹介をしていただければ大変ありがたいと思っているところです。","voiceIndex":106,"id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ちょっとその辺のことも含めて、ご見解をお願いします。そういったことから、ますますそういった啓発活動を町会・自治会を含めて行っていただきたいと、繰り返しの話になりますけれども、これは要望です。東京大会が終わった後もぜひそういった遺産を残して、ブラインドサッカーを引き続きやっていただきたいと思っています。","respondent":"池田スポーツ推進課長","answer":"私どものほうでは、荏原Ｂ地域スポーツクラブは特にそうなのですけれども、地域のスポーツクラブでグラウンド・ゴルフというのはかなり盛んになってまいりまして、こちらのほうでも地域のグラウンド・ゴルフの交流大会というもので一般の方が参加できるものにつきましては。","voiceIndex":109,"id":"exchange-049","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、そもそも障害者スポーツを行政が推進していく目的を教えてください。","respondent":"池田スポーツ推進課長","answer":"そういったことだけではなく、地域みんなでコミュニケーションをとりながら、いろいろなスポーツを楽しんで地域の輪をつくるということが現在一番の目的で、行政としましても障害者の方のスポーツということで、昭和５６年以降力を入れさせていただいているところです。","voiceIndex":111,"id":"exchange-050"},{"speaker":"藤原委員","kind":"提案","question":"今回、委員長、副委員長のご配慮で、うちの会派が提案させていただいたブラインドサッカー体験も実現していただいたのですけれども、やはり実際に体験してみるということで変わるのだなということを私は肌で感じたのは、このブラインドサッカーを体験するという話が出たときに、ある委員から、「私、あんまり行きたくない」というお話が実は出ていたのですけれども、実際に体験した後の発言を伺っていると。","respondent":"池田スポーツ推進課長、中山障害者福祉課長、小川オリンピック・パラリンピック準備課長","answer":"だけど、こういったユニバーサルスポーツ大会で皆さんとスポーツすることで、すごく楽しみができたという方もいらっしゃいますので。ですので、品川区は障害者スポーツに随分前から取り組んでいて、そういった土壌はしっかりあると考えていますので、これからもこうした場の活用と。ただ、ブラインドサッカーにこだわることなく、パラリンピック競技にはすばらしいスポーツがたくさんありますので、さまざまな機会を捉えて。","voiceIndex":113,"id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり私は、最初は躊躇したけれども、スポーツをしてみて、やってみてよかった、楽しかった、そういうふうになっていくことが一番の目標だと思っているので、ぜひスポーツ推進課と連携をして、行政として一歩踏み出す後押しをしていただきたいと心から思っているのですけれども、最後にそこだけ、もう一回答弁いただけますか。","respondent":"中山障害者福祉課長","answer":"ですので、できるだけ皆さんが気軽にできるようなメニューを提案しながら、体を動かす楽しみ、外に出ることの気持ちよさといったものを障害のある方に伝えていきたいと考えております。","voiceIndex":117,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ障害者の方々も日常的に楽しむことができるスポーツの一つではないかと思ったりするので、どのくらいの広さがあればできるのかも含めて教えていただきたいと思います。そして２つ目に、１番の障害者水泳教室、昭和５７年、相当前からやっていたということを改めてこの資料で確認したのですけれども、今年の障害者水泳教室は、私は恥ずかしいのですけれども初めて見に行きました。","respondent":"池田スポーツ推進課長","answer":"最初にグラウンド・ゴルフについてですけれども、グラウンド・ゴルフというのは、簡単に言いますとゴルフと同じようにスティックが１つ、それとボールがございまして、そのボールを、およそ３０ｍ先にポールを立てまして、そのポールのところに穴があるのですけれども。","voiceIndex":119,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私がスポーツセンターとか地方でやったときのグラウンド・ゴルフと相当イメージが違って、３０ｍという長さではなくてもっと短いものだったし、穴も相当大きいのですけれども、そこに入れるという感じだったので、ちょっと大分違うのだなと思ったのですけれども、しかし３０ｍはどうかわからないけれども、もう少し短距離にすれば本当に誰でも、小さな子どもでもできるというスポーツなのかなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"提案","question":"１点だけ伺います。藤原委員からもありましたし、吉田委員からもありました。南委員からもあったと思うのです。そこでちょっと先ほどもありましたが一歩踏み込んでいただいて、とっつきやすくする、ハードルを下げる何かそういう取り組みをしていただきたいと思うのですが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"私どものほうでやっているユニバーサルスポーツ大会やみんなでグラウンド・ゴルフというような催し物につきましては、私ども品川区のホームページに掲載をさせていただいて、ご案内をしていますけれども、今、委員のほうでお話がございました、それをバナーで一括で見せるですが。","voiceIndex":122,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、そこはやはり一覧にするというのが、本気で障害者スポーツに取り組む一歩踏み込んだ姿勢なのかなと思いますので、先ほど研究というお話がありましたが、ぜひともそういう取り組みをしていただきたいと思いますが、もう一回ご答弁をお願いいたします。","respondent":"池田スポーツ推進課長","answer":"委員からご意見のございましたこちらの問い合わせにつきましては、まずリンクができるかについては研究しますけれども、もう一つの情報の発信ということについて、もっと充実できるように、これは検討をするようにします。","voiceIndex":124,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この障害者スポーツというところで、私は今回の一般質問のところでも、品川区内に障害者スポーツセンターを建設していただきたいということも言ったのですけれども、城南５区のほうで設置を東京都に求めているということだったのですけれども、東京都の対応はどのようになっているのかというのを伺いたいです。もしやられていなければ、今後どう考えているのかというのを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"東京都につきましても、障害者スポーツ振興計画というものを策定しているところで、その中でもいろいろなアンケートを実施しているところでございまして、私どもはそちらの今現在直近で国・都でいろいろ調査をされている、アンケートをしているというのがありますので。","voiceIndex":126,"id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この障害者スポーツセンター、東京都から回答はないということですけれども、北区のほうの障害者スポーツセンターを視察に行ったときも、そこに行けば自分が何ができるかわからない方もスタッフと一緒に考えてもらえるということで、本当に自分に何ができるかというところから障害者の方々は始まるので、そういったことにしっかりと心を寄せて。","respondent":"池田スポーツ推進課長","answer":"例えば都内に２つある障害者スポーツセンターもそうですけれども、私どもの地域でやっているスポーツクラブがあれば、地域でやっているスポーツサークルのご案内をするというようなことで、障害をお持ちの方もまずはスポーツを体験していただいて。","voiceIndex":128,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、こうしたスポーツだけに特化した支援だけではなく、やはり移動等の支援だったり、バリアフリー、また支援スタッフが必ず常駐しているとか、そういったところを進めていかないと、スポーツというものに親しむことがなかなかできない、バリアがあり過ぎるという状況だと思うのですけれども、そういった生活全体から見て、障害者スポーツというところをどのように考えられているか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"そのために移動支援ですとか、視覚障害のある方のための同行援護といったサービスのほうもありますので、その方の活動に合わせて、そちらのほうは障害者福祉課で対応させていただいているところです。","voiceIndex":130,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"最後にしますけれども、やはりそういったところがまだまだ不十分だというのが障害を持たれた皆さんの実感ですので、そういったところをさらに私たちも一緒に求めていきたいと思いますので、ぜひ今後もご検討をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば１カ国全部やるというのは大変厳しい状況だと思います。品川区にそういうキャンプを誘致することができれば、小学校、中学校とのつながりもできることによって、これからの障害者スポーツにさらに結びつきができると思うのですが、その辺のお考えはいかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"事前キャンプにつきましては、オリンピックに限らずパラリンピックの面も視野に入れて、今、さまざま動いているところです。委員ご指摘のとおり、キャンプを誘致することによる効用は十分こちらも認識していますので、積極的にさまざま可能性のあるところで動いているところです。","voiceIndex":133,"id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ぜひお願いしたいです。そんな大規模なキャンプをやろうというと大変に厳しいところもあると思うので、ある程度競技を絞ってしまってもいいのではないかなというのは、この前会派の中の勉強会でもそんなイメージを持っているので、ぜひその辺をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"そういうところについてのご認識はどうなのかというのをまず伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"私どもとしましては、委員からご指摘のありました城南５区で考えてはどうかというようなこともありますけれども、まず東京都の動きを見定めてから、それからまた進めるような形になってくると思いますので、もう少し様子を見ていきたいなと考えています。","voiceIndex":136,"id":"exchange-063"},{"speaker":"南委員","kind":"質問","question":"様子を見たいということなのですが、それは一つの考え方かと思うけれども、様子を見るとなると、どのくらいの期間様子を見るのか、パラリンピックが終わってしまった後までなのか、ちょっとその辺があまりにもアバウトなので、わかりましたというふうには終われないので、そのあたりをちょっと伺います。","respondent":"池田スポーツ推進課長","answer":"区のほうも東京都の動きがどこまで動くかというところを見定めないと、城南５区としてどうなのかということができないかと考えていますので、そこのところはもう少し見定めるということで、よろしくお願いいたします。","voiceIndex":138,"id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"これが大きな眼目だと思うのです。そういう点でやはりいい機会だと思うので、やはりそういう方向をしっかり確認して取り組んでいくということが大事だと思うのです。したがって、場面によっては様子を見ることがあってもやむを得ないと思うけれども、やはり品川区のほうで積極的にアプローチをする、そしてできる方向で働きかけをするというスタンスで取り組んでいただきたいと考えています。","respondent":"池田スポーツ推進課長","answer":"委員のご意見はご意見として承りますけれども、あくまでも東京都の動きがないと、私どものほうでも考えるところが難しいと思いますので、しばらく東京都の動きを見させていただいて、その上で考えていきたいと思います。","voiceIndex":140,"id":"exchange-065"},{"speaker":"松永委員","kind":"質問","question":"この会場まで行かれるときに、先ほど課長がおっしゃっていましたが、手をつないで一緒に向かわれているというお話を聞いて、その選手たちがその会場まで行くにあたってのルートのところで、何かもうちょっとこうしてほしいなという意見がもし出ていたら、教えてください。","respondent":"池田スポーツ推進課長","answer":"もう一つ、駅からの動線ですけれども、西小山駅から角を２つ曲がると学校の校庭に着くということで、１つ目の角を曲がり、２つ目の角を曲がればすぐ着くということで、逆に角は２カ所曲がりますけれども、駅とそれから会場が近いということで。","voiceIndex":142,"id":"exchange-066"},{"speaker":"松永委員","kind":"質問","question":"そうすると、じゃあ、これはオープン、練習風景を外から見ることはできるということなのですね。そうなると、私は今日初めて知ったのですけれども、地域の周りの人たちというのはもうご存知なのかなということで、お伺いしたいと思います。","respondent":"池田スポーツ推進課長","answer":"ブラインド・サッカーの日本代表選手たちの練習につきましては、これは学校長もかなり協力的でございまして、ブラインド・サッカーの選手たちが毎週火曜日の夜ですけれども、練習をしているということで生徒たちにも周知していますし。","voiceIndex":144,"id":"exchange-067"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはり障害者スポーツを振興するに際して、このパラリンピックにおいてのキャンプ誘致というのは非常に区民も誇りを持てる部分にもなってきますし、逆に品川区内の障害をお持ちの皆さんにとっても、今後の自分たちの生きる未来が開けるというか、本当に希望の光だと思いますので、その辺をどうお考えか、どのぐらいのやる気があるのかというところを含めてちょっと教えていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"事前キャンプについて、品川区を当時ＰＲをさせていただいて、リオが終わったら考えるという回答を得まして、その後、委員ご指摘のとおりさまざまなルートを使って積極的にまさに水面下で動いているところです。","voiceIndex":146,"id":"exchange-068"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひこの報告書、手前みそになってしまうと思うのですけれども大変よくできていて、非常に見甲斐があって、その一つ一つがやはり細かいミクロの部分で見ていくと本当に参考になるものなので、しっかりと活かす方向に持っていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-069"},{"speaker":"つる委員","kind":"確認","question":"その中では、例えば理学療法士の方とか、そういう補装具等をつくられている義肢装具士の方とか、そういう方にフォーカスをした何か講演とか機会は、この間、オリンピック・パラリンピック推進特別委員会とかオリンピック・パラリンピック準備課等を設けた以降で何かあったかどうか、まず確認したいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"オリンピック・パラリンピックに取り組んだのが３年前からですけれども、その３年前から、パラリンピックに焦点を当てた啓発の講演会をしています。第１回目はパラリンピアンであります佐藤真海さんを呼ばせていただきました。","voiceIndex":149,"id":"exchange-070","title":"町会・自治会支援"},{"speaker":"つる委員","kind":"質問・要望","question":"そういったことももう少し専門的にやられているような方々、その人がどういうパフォーマンスをアップできるように常日ごろ考えているのか。例えば今後平成２９年、平成３０年、オリンピック本番が始まるまでの間の中でも、こういったものも活用しながら、そういう機会をぜひつくっていただきたいと思うのですが、何か考えがあればぜひ教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった中で、品川区は今のところすべて限度額ぎりぎりいっぱいまで品川区の事業で使う見込みとなっています。そういった中でも平成２９年以降、委員ご指摘のあったようなこともヒントにさせていただきながら、いろいろ展開をして考えてまいりたいと思います。","voiceIndex":151,"id":"exchange-071","title":"町会・自治会支援"},{"speaker":"つる委員","kind":"意見","question":"ぜひ、よろしくお願いします。どうしてもそういう推進とかとなると、冒頭申し上げたように、選手そのものにしかフォーカスが当たらないケースはよくあるので、実はその方を支えている方がたくさんいるのだと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-072"},{"speaker":"南委員","kind":"質問","question":"そういう扱いでいいと思うのですけれども、今、委員長がおっしゃった分野が広いので分野別にという、そこの分野別というのは具体的に項目で言うと何ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"大分用意してきたのですけれども、今日はもうやらないということで、先ほどオリンピック・パラリンピック準備課長の説明の中で、東京２０２０参画プログラムがイコール文化プログラムではないということにご注意くださいとあったのですけれども、そこの違いについて教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今回の組織委員会がさきに始めました東京２０２０参画プログラムというのは、ＩＯＣに認証を得るものではなく、組織委員会があくまでも認証するというものですので、今後これがどう文化プログラムに展開されていくのか。","voiceIndex":162,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"意見","question":"わかりました。次回、またそういうわかりやすい比較の資料を用意していただけるということなので、そちらのほうを見ながら、また品川区でどのようなことができるのか検討していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問","question":"東京２０２０応援プログラムのほうも、これはちょっと来年度本格開始というのですけれども、その認証事業開始とか本格開始とか、この意味がちょっと僕はわからなくて、どういう意味なのかというのを教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらに書いてありますスケジュール、１０月１日から認証事業開始とありまして、品川区のほうにも事前にこういったプログラムの照会等はございました。","voiceIndex":165,"id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問・要望","question":"考え方としては、申請開始は例えば平成２８年８月１５日と書かれているのですけれども、申請というのは要は締切日がなくて、随時受付をしていて、認証開始は、８月１５日に申請をしても１０月１日以降ですよという解釈でいいのかどうなのかということと、ぜひ、何か今、無電柱化というのは、もちろんこの中にまちづくりというのがあるので、しかも長期間それは整備するのにかかるので。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"時間がかかって、何度も何度もやり取りしなければならないということで、職員も相当ハードな、忍耐的な労力がいっぱいかかっているという状況ですので、区としては、プログラムが認証されようがされまいがやることはきちんとやるというスタンスでいきたいと考えています。","voiceIndex":167,"id":"exchange-077"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ偏った認証というよりは、むしろ品川区全般的な分野というか、この経済・テクノロジー、復興、オールジャパン・世界への発信等々というのは全部該当する事業があろうかと思いますので、そういうのにぜひ使用できるようにやっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-078"},{"speaker":"伊藤委員","kind":"質問","question":"東京２０２０参画プログラムと、それから品川区民芸術祭のことについて質問します。東京２０２０参画プログラムですけれども、スケジュールのところで申請開始と認証事業開始とあるのですけれども、今の話に続けますけれども、これはどこに申請をするのかということ、それから、どこの誰がどういう権限でその内容を審査するのかということをお聞かせください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"申請は必ず東京都を通じて組織委員会にいたします。認証を行うのは大会組織委員会です。","voiceIndex":170,"id":"exchange-079"},{"speaker":"伊藤委員","kind":"確認","question":"その認証の中にオリンピック憲章が絡んでくるからという話になっていると思うのだけれども、そうですか、そうすると非常にハードルが高いですね。わかりました。そのことの確認です。そのことを教えてください。どのようなかかわり方なのでしょうか。","respondent":"鈴木文化観光課長","answer":"企画展につきましては、これは相手の団体によりまして幾つかパターンがありますが、基本的には品川区のほうの共催または後援等の名義をとっていただいて、実施主体が中心となってやったいただくものが主に含まれているものです。","voiceIndex":172,"id":"exchange-080"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、そうすると、例えばしながわアマチュアステージのところは各団体に募集をして、手挙げして申し込みをして、例えばその枠を振り分けていくのでしょうかということ、同じように、企画展も相手がやらなかったらやらないと言ったら変ですけれども、企画展の部分では団体が何もしない可能性があるのでしょうかということ。そういうことからすると協賛事業もそうですよね。","respondent":"鈴木文化観光課長","answer":"こちらは品川区も絡んでいることもありますけれども、基本的には文化振興事業団やＯ美術館、それから寺田倉庫さんのように、やはり品川区とかかわりの強い、普段から連携をしていただいている事業者や団体が連携をしてやるということですので、毎年大体七。","voiceIndex":174,"id":"exchange-081"},{"speaker":"伊藤委員","kind":"確認","question":"そんなに難しい話ではないので、確認だけなのですけれども、例えば協賛事業や企画展については、当然品川区のガイドラインと言ったらいいのかな、審査のようなものがあるのでしょうか。同じようにサークル活動のしながわアマチュアステージの件についても同じですが、いかがですか。それだけ教えてください。","respondent":"鈴木文化観光課長","answer":"これは、ほかの例えばスポーツであったり、それから区民の方のいろいろな活動についても適用されている制度でございまして、基本的には区民の方広くにいろいろなよい効果が出る事業、それから特別な営利目的や政治的な目的を持っていないというような部分の基準がありまして。","voiceIndex":176,"id":"exchange-082"},{"speaker":"南委員","kind":"質問","question":"舟運・水辺の利活用のこととボランティアの育成・確保、そして交通整備（３５７号線、輸送計画）。交通整備は選手の輸送だとか、私たち観光客の輸送だとかというかかわりだと思うのだけれども、３５７号線というのは、あちらの潮風公園との関係で入ってくるという理解でよろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-083"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"委員長、どうしてもお伺いしたいのですけれども、先日区民委員会で、都議会自民党がビーチバレーボールの会場について抜本的に見直すべきとの提言がされたと伺ったのですけれども、それにあたって、品川区のオリンピック・パラリンピック推進特別委員会の委員長としてどう思われるのかと、具体的にオリンピック・パラリンピック推進特別委員会という意味において、何か行動をしていくお考えがあるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":78200,"voices":191}},{"id":"h28-20161206-10","meetingId":"h28-cm12","date":"2016年12月6日","dateIso":"2016-12-06","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"途中ではありますが、先に予定表３、その他の(2)東京都後期高齢者医療広域連合議会の報告","agenda":"途中ではありますが、先に予定表３、その他の(2)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"１件だけ。私たちとしては、軽減措置がなくなるにあたって、本当になくなってしまったら大変なので、例えば東京都にそのかわりを求めていくとか、何か手だてがないのかと思っているのですが、その辺の議論がどのようであったか教えていただきたい。","respondent":"本多議員","answer":"極力、公平性を維持しながら、引き上げを極力しない方法で考えたというのは、答弁の中でありましたので、そういった課題・指摘等は、やはり会議の中で出ておりましたが、執行側としては「極力抑えました」という、そういった説明をしておりました。","voiceIndex":15,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":11582,"voices":45}}]);
